for week in WEEKS:
    entries = []
    for index, (file, title, topics, code, outcome, caution) in enumerate(week['lessons'], 1):
        prefix = f"week-{week['id']}/docs/"
        from posixpath import normpath
        entries.append(dict(id=index, file=normpath(prefix+file), title=title,
                            topics=topics, code=code, outcome=outcome, caution=caution))
    week['lessons'] = entries
